function verificationPanel(e){const v=e.verification||{},fresh=['reviewed','listed'].includes(verificationState(e)),label=k=>t('trust'+k[0].toUpperCase()+k.slice(1)),known=v.verified_fields||[],unknown=verificationFields.filter(k=>!known.includes(k));return `<section class="verification-panel" aria-label="${escape(t('trustTitle'))}"><strong>${escape(trustLabel(e))}</strong>${v.checked_at?`<p>${escape(t(e.provider==='tourapi'?'trustAPICheckedAt':'trustCheckedAt'))} <time datetime="${escape(v.checked_at)}">${escape(new Intl.DateTimeFormat(state.lang,{timeZone:'Asia/Seoul',dateStyle:'medium',timeStyle:'short'}).format(new Date(v.checked_at)))} KST</time></p>`:''}${known.length?`<p><b>${escape(t('trustKnown'))}</b> · ${escape(known.map(label).join(' · '))}</p>`:''}<p><b>${escape(t('trustUnknown'))}</b> · ${escape((fresh?unknown:verificationFields).map(label).join(' · '))}</p>${!maySuggest(e)?`<p>${escape(t('trustCourseHeld'))}</p>`:''}<details><summary>${escape(t('trustSources'))}</summary>${(v.sources||[]).map(s=>`<p><a target="_blank" rel="noopener noreferrer" href="${safeURL(s.url)}">${escape(new URL(s.url).hostname)} ↗</a><br><small>${escape(s.fields.map(label).join(' · '))}</small></p>`).join('')}${v.notes_ko?`<p><b>${escape(t('trustNotes'))}</b></p><p lang="ko">${escape(v.notes_ko)}</p>`:''}<p>${escape(t('trustSourceMode'))}: ${escape(t(v.method==='tourapi_import'?'trustTourAPIDetail':v.cached_source?'trustCached':'trustDirect'))}</p>${v.additional_unknowns?.length?`<p lang="ko">${escape(v.additional_unknowns.join(' · '))}</p>`:''}<p>${escape(t('trustPolicy'))}</p></details></section>`;}

